// Merge(append)の出力から4ブランチをフィールド名で分類
// _src === 'keystone_hp' でキーストンHPタスクを区別
// $() クロス参照なし → Execute step でも動く
const allItems  = $input.all().map(i => i.json);
const tasks     = allItems.filter(item => item['タスク名'] !== undefined && item._src !== 'keystone_hp');
const ksTasks   = allItems.filter(item => item['タスク名'] !== undefined && item._src === 'keystone_hp');
const deals     = allItems.filter(item => item['Deal名']   !== undefined);
let pendingAll  = {};
const gasItem   = allItems.find(item => item.success !== undefined && item.members !== undefined);
if (gasItem && gasItem.success && gasItem.members) pendingAll = gasItem.members;

// memberName → chatId
const MEMBER_MAP = {
  '宮脇':   '1074258418',
  '吉岡':   '6427868789',
  '小林':   '7669101392',
  '高田':   'FILL_ME_CHAT_ID_takada',
  '北庄司': '8857512747'
};

const today = new Date(); today.setHours(0, 0, 0, 0);
const todayStr = `${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(today.getDate()).padStart(2,'0')}`;

function daysDiff(ds) {
  if (!ds) return null;
  const d = new Date(ds); if (isNaN(d)) return null;
  d.setHours(0, 0, 0, 0);
  return Math.floor((today - d) / 86400000);
}

const T = { name:'タスク名', assignee:'担当', priority:'優先度', due:'期限', status:'ステータス' };
const D = { name:'Deal名', assignee:'担当者', priority:'優先度', status:'ステータス',
            nextDate:'次回コンタクト予定日', nextAction:'次回アクション', phase:'フェーズ' };

const items = [];
for (const [memberName, chatId] of Object.entries(MEMBER_MAP)) {
  if (chatId.startsWith('FILL_ME')) continue;

  const myTasks   = tasks.filter(t => t[T.assignee] === memberName && t[T.status] !== '済');
  const overTasks = myTasks.filter(t => (daysDiff(t[T.due]) ?? -1) > 0);
  const todTasks  = myTasks.filter(t => daysDiff(t[T.due]) === 0);

  const myDeals   = deals.filter(d => d[D.assignee] === memberName && d[D.status] === '進行中');
  const overDeals = myDeals.filter(d => (daysDiff(d[D.nextDate]) ?? -1) > 0);
  const todDeals  = myDeals.filter(d => daysDiff(d[D.nextDate]) === 0);

  const pending = pendingAll[memberName] || [];

  // キーストンHPタスクは北庄司専用（全件 未済のみ）
  const myKsTasks = memberName === '北庄司'
    ? ksTasks.filter(t => t[T.status] !== '済')
    : [];

  items.push({ memberName, chatId, todayStr,
               overTasks, todTasks, overDeals, todDeals,
               pending, ksTasks: myKsTasks });
}

return items;

const d = $input.first().json;

function fmtDate(ds) {
  if (!ds) return '?';
  const dt = new Date(ds); if (isNaN(dt)) return ds;
  return `${dt.getFullYear()}-${String(dt.getMonth()+1).padStart(2,'0')}-${String(dt.getDate()).padStart(2,'0')}`;
}
function daysDiff(ds) {
  if (!ds) return null;
  const t = new Date(); t.setHours(0,0,0,0);
  const dd = new Date(ds); dd.setHours(0,0,0,0);
  return Math.floor((t - dd) / 86400000);
}

const T = { name:'タスク名', priority:'優先度', due:'期限' };
const D = { name:'Deal名', priority:'優先度', nextDate:'次回コンタクト予定日', nextAction:'次回アクション' };

let msg = `☀️ おはようございます、*${d.memberName}*さん\n`;
msg += `📅 ${d.todayStr}\n`;
msg += `━━━━━━━━━━━━━━\n\n`;

if (d.overTasks.length > 0) {
  msg += `🔴 *期限超過タスク* (${d.overTasks.length}件)\n`;
  d.overTasks.forEach((t, i) => {
    msg += `${i+1}. 【${t[T.priority]||'-'}】${t[T.name]}\n`;
    msg += `   期限:${fmtDate(t[T.due])}（${daysDiff(t[T.due])}日経過）\n`;
  });
  msg += '\n';
}

if (d.todTasks.length > 0) {
  msg += `🟡 *本日期限タスク* (${d.todTasks.length}件)\n`;
  d.todTasks.forEach((t, i) => {
    msg += `${i+1}. 【${t[T.priority]||'-'}】${t[T.name]}\n`;
  });
  msg += '\n';
}

if (d.overDeals.length > 0) {
  msg += `🔴 *コンタクト超過 Deal* (${d.overDeals.length}件)\n`;
  d.overDeals.forEach((deal, i) => {
    msg += `${i+1}. 【${deal[D.priority]||'-'}】${deal[D.name]}\n`;
    msg += `   ${daysDiff(deal[D.nextDate])}日超過 / ${deal[D.nextAction]||'(未設定)'}\n`;
  });
  msg += '\n';
}

if (d.todDeals.length > 0) {
  msg += `🟢 *本日コンタクト予定* (${d.todDeals.length}件)\n`;
  d.todDeals.forEach((deal, i) => {
    msg += `${i+1}. 【${deal[D.priority]||'-'}】${deal[D.name]}\n`;
    msg += `   ${deal[D.nextAction]||'(未設定)'}\n`;
  });
  msg += '\n';
}

if (d.pending.length > 0) {
  msg += `📝 *昨日の未完了タスク*\n`;
  d.pending.forEach(t => {
    msg += `☐ ${t.replace(/^- \[ \] /, '')}\n`;
  });
  msg += '\n';
}

// キーストンHPタスク（北庄司のみ表示）
if (d.ksTasks && d.ksTasks.length > 0) {
  msg += `📋 *キーストンHPタスク* (${d.ksTasks.length}件)\n`;
  d.ksTasks.forEach((t, i) => {
    const diffVal = daysDiff(t['期限']);
    const overStr = diffVal !== null && diffVal > 0 ? `（${diffVal}日超過）` : '';
    msg += `${i+1}. 【${t['優先度']||'-'}】${t['タスク名']}\n`;
    if (t['期限']) msg += `   期限:${fmtDate(t['期限'])}${overStr}\n`;
  });
  msg += '\n';
}

const hasNothing = !d.overTasks.length && !d.todTasks.length &&
                   !d.overDeals.length && !d.todDeals.length &&
                   !d.pending.length   && !(d.ksTasks && d.ksTasks.length);
if (hasNothing) {
  msg += `✅ 本日の要対応事項はありません\n良い一日を！\n`;
}

msg += `━━━━━━━━━━━━━━`;

return { chatId: d.chatId, text: msg };
